mapper.select:
        SELECT m.ai_message_id, m.content, m.role, m.create_time
        FROM t_ai_message m
        INNER JOIN t_ai_conversation c
                ON c.ai_conversation_id = m.ai_conversation_id
        WHERE m.ai_conversation_id = #{aiConversationId}
          AND c.user_id = #{userId}


            AND m.ai_message_id < #{lastCursorId}
        

        ORDER BY m.ai_message_id DESC
        LIMIT #{size}

        SELECT m.content, m.role
        FROM t_ai_message m
        INNER JOIN t_ai_conversation c
                ON c.ai_conversation_id = m.ai_conversation_id
        WHERE m.ai_conversation_id = #{aiConversationId}
          AND c.user_id = #{userId}


            AND m.ai_model_config_id = #{aiModelConfigId}
